CREATE OR REPLACE FUNCTION public.get_dashboard_metrics()
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
  result json;
  kpi_total int;
  kpi_waiting int;
  kpi_value numeric;
  pipelines_data json;
BEGIN
  -- KPIs Gerais
  SELECT count(*) INTO kpi_total FROM clients;
  SELECT count(*) INTO kpi_waiting FROM clients WHERE unread_messages_count > 0;
  SELECT coalesce(sum(deal_value), 0) INTO kpi_value FROM clients;

  -- Dados por Pipeline
  SELECT json_agg(p_data) INTO pipelines_data FROM (
    SELECT 
      p.id,
      p.name,
      p.slug,
      count(c.id) as total_leads,
      coalesce(sum(c.deal_value), 0) as total_value,
      count(c.id) FILTER (WHERE c.unread_messages_count > 0) as waiting_response
    FROM pipelines p
    LEFT JOIN clients c ON c.pipeline_id = p.id
    GROUP BY p.id, p.name, p.slug
    ORDER BY p.id
  ) p_data;

  RETURN json_build_object(
    'kpis', json_build_object(
      'total_clients', kpi_total,
      'waiting_response', kpi_waiting,
      'total_value', kpi_value
    ),
    'pipelines', coalesce(pipelines_data, '[]'::json)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_real_estate_metrics()
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
    result json;
BEGIN
    SELECT json_build_object(
        'waiting_leads', (SELECT count(*) FROM view_whatsapp_monitoring WHERE pending_reply = true),
        'visits_scheduled', (SELECT count(*) FROM leads WHERE stage = 'Visita'),
        'active_proposals', (SELECT count(*) FROM leads WHERE stage = 'Proposta'),
        'avg_wait_time', (SELECT coalesce(round(avg(minutes_waiting)::numeric, 0), 0) FROM view_whatsapp_monitoring WHERE pending_reply = true)
    ) INTO result;
    return result;
END;
$function$
